#### Phase 2: Implement Core Batching Logic

1. **Create Event Batcher Component (Java Example)**

   ```java
   @Component
   public class EventBatcher<T> {
       private final Map<String, ConcurrentLinkedQueue<T>> buffers = new ConcurrentHashMap<>();
       private final Map<String, Long> firstEventTimestamp = new ConcurrentHashMap<>();
       private final BatchConfiguration config;
       private final AsyncEventPublisher publisher;
       private final ScheduledExecutorService scheduler;

       public EventBatcher(BatchConfiguration config, AsyncEventPublisher publisher) {
           this.config = config;
           this.publisher = publisher;
           this.scheduler = Executors.newScheduledThreadPool(2);

           // Start flush coordinator
           scheduler.scheduleAtFixedRate(this::checkAndFlush, 50, 50, TimeUnit.MILLISECONDS);
       }

       public void emit(String topic, T event) {
           // Get or create buffer for topic
           ConcurrentLinkedQueue<T> buffer = buffers.computeIfAbsent(
               topic, k -> new ConcurrentLinkedQueue<>()
           );

           // Track first event timestamp
           firstEventTimestamp.putIfAbsent(topic, System.currentTimeMillis());

           // Add event to buffer (non-blocking)
           buffer.offer(event);

           // Check if immediate flush needed (size threshold exceeded)
           if (buffer.size() >= config.getBatchSize(topic)) {
               flushTopic(topic);
           }
       }

       private void checkAndFlush() {
           for (String topic : buffers.keySet()) {
               ConcurrentLinkedQueue<T> buffer = buffers.get(topic);
               if (buffer.isEmpty()) continue;

               // Check time-based trigger
               long firstTimestamp = firstEventTimestamp.getOrDefault(topic, 0L);
               long elapsed = System.currentTimeMillis() - firstTimestamp;

               if (elapsed >= config.getLingerMs(topic)) {
                   flushTopic(topic);
               }
           }
       }

       private void flushTopic(String topic) {
           ConcurrentLinkedQueue<T> buffer = buffers.get(topic);
           if (buffer == null || buffer.isEmpty()) return;

           // Extract events from buffer
           List<T> batch = new ArrayList<>();
           T event;
           while ((event = buffer.poll()) != null && batch.size() < config.getBatchSize(topic)) {
               batch.add(event);
           }

           if (!batch.isEmpty()) {
               // Reset timestamp
               firstEventTimestamp.remove(topic);

               // Publish batch asynchronously
               publisher.publishBatch(topic, batch)
                   .thenAccept(result -> onPublishSuccess(topic, batch.size()))
                   .exceptionally(ex -> onPublishFailure(topic, batch, ex));
           }
       }
   }
   ```

2. **Implement Async Publisher with Kafka**

   ```java
   @Component
   public class KafkaAsyncPublisher implements AsyncEventPublisher {
       private final KafkaTemplate<String, Object> kafkaTemplate;
       private final MeterRegistry metrics;

       @Override
       public CompletableFuture<SendResult> publishBatch(String topic, List<Object> events) {
           // Create batch record
           ProducerRecord<String, Object> batchRecord = new ProducerRecord<>(
               topic,
               null,  // partition determined by key
               createBatchPayload(events)
           );

           // Send asynchronously
           ListenableFuture<SendResult<String, Object>> future =
               kafkaTemplate.send(batchRecord);

           // Convert to CompletableFuture
           CompletableFuture<SendResult> result = new CompletableFuture<>();
           future.addCallback(
               success -> {
                   recordMetrics(topic, events.size(), true);
                   result.complete(success);
               },
               failure -> {
                   recordMetrics(topic, events.size(), false);
                   result.completeExceptionally(failure);
               }
           );

           return result;
       }

       private BatchPayload createBatchPayload(List<Object> events) {
           return BatchPayload.builder()
               .events(events)
               .batchSize(events.size())
               .timestamp(System.currentTimeMillis())
               .build();
       }
   }
   ```

